"""Querying and adjusting the privileges held by the current process."""

from .errors import WTokenError
from ._winapi import (
    is_windows,
    open_process_token,
    close_handle,
    lookup_privilege_value,
    lookup_privilege_name,
    get_token_privileges,
    adjust_token_privileges,
    TOKEN_QUERY,
    TOKEN_ADJUST_PRIVILEGES,
    SE_PRIVILEGE_ENABLED,
)


def _require_windows(operation="this operation"):
    if not is_windows():
        raise WTokenError(
            "%s requires Windows" % operation,
            kind="unsupported",
        )


def _luid_to_int(luid):
    """Convert a LUID struct to a 64-bit integer for hashing/comparison."""
    return (luid.HighPart << 32) | luid.LowPart


def privileges():
    """Return ``{name: enabled}`` for every privilege the token holds.

    Each key is the privilege name and each value is ``True`` when the
    privilege is currently enabled on the token, ``False`` when it is held
    but disabled.
    """
    _require_windows("privilege enumeration")
    token = None
    try:
        token = open_process_token(TOKEN_QUERY)
        items = get_token_privileges(token)
    except OSError as exc:
        raise WTokenError("could not read token privileges: %s" % exc, kind="os") from exc
    finally:
        if token is not None:
            try:
                close_handle(token)
            except Exception:
                pass

    result = {}
    for luid, attrs in items:
        try:
            name = lookup_privilege_name(luid)
        except OSError:
            # Skip privileges whose names cannot be resolved; this should be
            # extremely rare and only happens for custom / unregistered values.
            continue
        enabled = bool(attrs & SE_PRIVILEGE_ENABLED)
        result[name] = enabled
    return result


def has_privilege(name):
    """Return ``True`` when the token holds ``name``, regardless of whether
    the privilege is currently enabled."""
    if not isinstance(name, str) or not name:
        return False
    _require_windows("privilege queries")
    token = None
    try:
        token = open_process_token(TOKEN_QUERY)
        items = get_token_privileges(token)
    except OSError:
        return False
    finally:
        if token is not None:
            try:
                close_handle(token)
            except Exception:
                pass

    # Resolve the requested name to its LUID so we can compare numerically.
    try:
        target_luid = lookup_privilege_value(name)
    except OSError:
        # The system doesn't know this privilege name at all.
        return False

    target_int = _luid_to_int(target_luid)
    for luid, _attrs in items:
        if _luid_to_int(luid) == target_int:
            return True
    return False


def set_privilege(name, enabled=True):
    """Switch a held privilege on or off.

    Raises :class:`WTokenError` with ``kind="badarg"`` when the name is empty
    or unknown, ``kind="os"`` when the system refuses the change (for example
    because the privilege is not held), and ``kind="unsupported"`` when the
    runtime cannot perform the operation at all.
    """
    if not isinstance(name, str) or not name:
        raise WTokenError(
            "a non-empty privilege name is required",
            kind="badarg",
            privilege=name,
        )
    _require_windows("privilege adjustment")

    # Resolve the name to a LUID first; this validates the name.
    try:
        luid = lookup_privilege_value(name)
    except OSError as exc:
        raise WTokenError(
            "unknown privilege: %r" % (name,),
            kind="badarg",
            privilege=name,
        ) from exc

    token = None
    try:
        token = open_process_token(TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY)
        adjust_token_privileges(token, luid, bool(enabled))
    except OSError as exc:
        errno = getattr(exc, "args", (0,))[0] if exc.args else 0
        # ERROR_NOT_ALL_ASSIGNED (1300) means the privilege is not held.
        if errno == 1300:
            raise WTokenError(
                "the token does not hold %r" % (name,),
                kind="badarg",
                privilege=name,
            ) from exc
        raise WTokenError(
            "could not adjust %r: %s" % (name, exc),
            kind="os",
            privilege=name,
        ) from exc
    finally:
        if token is not None:
            try:
                close_handle(token)
            except Exception:
                pass


def privilege_luid(name):
    """Return the locally unique identifier the system uses for ``name``.

    The returned value is the same integer the kernel associates with the
    privilege and can be passed back to :func:`privilege_name`.
    """
    if not isinstance(name, str) or not name:
        raise WTokenError(
            "a non-empty privilege name is required",
            kind="badarg",
            privilege=name,
        )
    _require_windows("privilege lookups")
    try:
        luid = lookup_privilege_value(name)
    except OSError as exc:
        raise WTokenError(
            "unknown privilege: %r" % (name,),
            kind="badarg",
            privilege=name,
        ) from exc
    return _luid_to_int(luid)


def privilege_name(luid):
    """Return the privilege name for an identifier previously obtained from
    :func:`privilege_luid`."""
    _require_windows("privilege lookups")
    try:
        luid_int = int(luid)
    except (TypeError, ValueError):
        raise WTokenError(
            "a privilege identifier must be an integer, got %r" % (luid,),
            kind="badarg",
        )

    if luid_int < 0 or luid_int > 0xFFFFFFFFFFFFFFFF:
        raise WTokenError(
            "unknown privilege identifier: %r" % (luid,),
            kind="badarg",
        )

    from ._winapi import LUID
    struct = LUID()
    struct.LowPart = luid_int & 0xFFFFFFFF
    struct.HighPart = (luid_int >> 32) & 0xFFFFFFFF

    try:
        return lookup_privilege_name(struct)
    except OSError as exc:
        raise WTokenError(
            "unknown privilege identifier: %r" % (luid,),
            kind="badarg",
        ) from exc

"""Elevation and integrity state of the current process."""

from .errors import WTokenError
from ._winapi import (
    is_windows,
    open_process_token,
    close_handle,
    get_token_elevation,
    get_token_integrity_level,
    TOKEN_QUERY,
    TokenElevationTypeDefault,
    TokenElevationTypeFull,
    TokenElevationTypeLimited,
)


_ELEVATION_TYPE_NAMES = {
    TokenElevationTypeDefault: "default",
    TokenElevationTypeFull: "full",
    TokenElevationTypeLimited: "limited",
}

_INTEGRITY_RID_NAMES = {
    0x0000: "untrusted",
    0x1000: "low",
    0x2000: "medium",
    0x2100: "medium-plus",
    0x3000: "high",
    0x4000: "system",
    0x5000: "protected-process",
}


def elevation():
    """Return ``{"elevated": bool, "type": str}`` for the current token.

    ``elevated`` is ``True`` when the token carries a full administrative
    credential set.  ``type`` is one of ``"default"``, ``"full"`` or
    ``"limited"`` and reflects the elevation type reported by the kernel.
    """
    if not is_windows():
        raise WTokenError(
            "elevation queries require Windows",
            kind="unsupported",
        )

    token = None
    try:
        token = open_process_token(TOKEN_QUERY)
        is_elevated, etype = get_token_elevation(token)
    except OSError as exc:
        raise WTokenError(
            "could not query token elevation: %s" % exc,
            kind="os",
        ) from exc
    finally:
        if token is not None:
            try:
                close_handle(token)
            except Exception:
                pass

    type_name = _ELEVATION_TYPE_NAMES.get(etype, "unknown")
    return {"elevated": is_elevated, "type": type_name}


def integrity_level():
    """Return the mandatory integrity level of the current token as a string.

    The returned value is one of the well-known level names such as
    ``"medium"`` or ``"high"``.
    """
    if not is_windows():
        raise WTokenError(
            "integrity queries require Windows",
            kind="unsupported",
        )

    token = None
    try:
        token = open_process_token(TOKEN_QUERY)
        rid = get_token_integrity_level(token)
    except OSError as exc:
        raise WTokenError(
            "could not query token integrity level: %s" % exc,
            kind="os",
        ) from exc
    finally:
        if token is not None:
            try:
                close_handle(token)
            except Exception:
                pass

    # Try exact match first, then fall back to nearest lower known RID so we
    # still produce a meaningful name for intermediate values.
    name = _INTEGRITY_RID_NAMES.get(rid)
    if name is None:
        known = sorted(_INTEGRITY_RID_NAMES.keys())
        fallback = None
        for k in known:
            if k <= rid:
                fallback = _INTEGRITY_RID_NAMES[k]
            else:
                break
        name = fallback or "unknown"
    return name

